package com.kuaixietech.shops;
import com.kuaixietech.security.DomainAccessGuard;
import jakarta.validation.constraints.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
@Service
public class ShopService {
 private final JdbcTemplate db;private final DomainAccessGuard guard;
 public ShopService(JdbcTemplate db,DomainAccessGuard guard){this.db=db;this.guard=guard;}
 public record Application(@NotBlank @Size(max=200) String businessName,@NotBlank @Pattern(regexp="[0-9A-HJ-NPQRTUWXY]{18}") String creditCode,@NotBlank @Size(max=100) String representative,@NotBlank String licenseUploadId,@Size(max=16) String invitationCode,@NotBlank @Pattern(regexp="web|h5|app|mp_weixin") String channel,@NotBlank String requestId){}
 public record Review(boolean approve,@NotBlank @Size(max=1000) String reason){}
 public record Edit(@NotBlank @Size(max=200) String name,@Size(max=1000) String description){}
 public record State(@NotBlank @Pattern(regexp="active|paused|suspended") String status,@NotBlank String expectedStatus,@NotBlank @Size(max=1000) String reason){}
 public record Link(@NotBlank String productId){}
 private Map<String,Object> row(String sql,Object...args){return db.queryForList(sql,args).stream().findFirst().orElse(null);}
 private ResponseStatusException fail(HttpStatus code,String reason){return new ResponseStatusException(code,reason);}
 private void changed(int count){if(count!=1)throw new IllegalStateException("SHOP_CONCURRENT_CHANGE");}
 private void lockOwner(String user){if(row("SELECT id FROM t_profiles WHERE id=? AND deleted_at IS NULL FOR UPDATE",user)==null)throw fail(HttpStatus.NOT_FOUND,"SHOP_ACCOUNT_UNAVAILABLE");}
 private String id(String request){try{return UUID.fromString(request).toString();}catch(Exception e){throw fail(HttpStatus.BAD_REQUEST,"SHOP_REQUEST_ID_REQUIRED");}}
 static boolean validCreditCode(String code){if(code==null||code.length()!=18)return false;String chars="0123456789ABCDEFGHJKLMNPQRTUWXY";int[] weights={1,3,9,27,19,26,16,17,20,29,25,13,8,24,10,30,28};int sum=0;for(int i=0;i<17;i++){int n=chars.indexOf(code.charAt(i));if(n<0)return false;sum+=n*weights[i];}return chars.charAt((31-sum%31)%31)==code.charAt(17);}
 public Map<String,Object> mine(){String user=guard.requireActiveProfile();var store=row("SELECT id,name,description,matching_fee_rate,status,application_id,created_at FROM t_stores WHERE owner_id=?",user);var applications=db.queryForList("SELECT id,business_name,unified_social_credit_code,legal_representative,license_upload_id,invitation_code,application_channel,status,review_note,reviewed_at,created_at FROM t_store_applications WHERE user_id=? ORDER BY created_at DESC,id DESC LIMIT 100",user);var result=new LinkedHashMap<String,Object>();result.put("store",store);result.put("applications",applications);result.put("products",store==null?List.of():db.queryForList("SELECT p.id,p.name,p.status,p.stock,p.price FROM t_store_products s JOIN t_products p ON p.id=s.product_id WHERE s.store_id=? ORDER BY s.created_at DESC,p.id LIMIT 100",store.get("id")));return result;}
 @Transactional public Map<String,String> apply(Application input){String user=guard.requireActiveProfile();lockOwner(user);String request=id(input.requestId()),application=UUID.nameUUIDFromBytes(("shop:"+user+":"+request).getBytes(StandardCharsets.UTF_8)).toString();var prior=row("SELECT id,business_name,unified_social_credit_code,legal_representative,license_upload_id,invitation_code,application_channel,status FROM t_store_applications WHERE id=? AND user_id=? FOR UPDATE",application,user);String invite=input.invitationCode()==null||input.invitationCode().isBlank()?null:input.invitationCode().trim();if(prior!=null){if(!Objects.equals(prior.get("business_name"),input.businessName().trim())||!Objects.equals(prior.get("unified_social_credit_code"),input.creditCode())||!Objects.equals(prior.get("legal_representative"),input.representative().trim())||!Objects.equals(prior.get("license_upload_id"),input.licenseUploadId())||!Objects.equals(prior.get("invitation_code"),invite)||!Objects.equals(prior.get("application_channel"),input.channel()))throw fail(HttpStatus.CONFLICT,"SHOP_REQUEST_REUSED");return Map.of("id",application,"status",prior.get("status").toString());}
  if(!validCreditCode(input.creditCode()))throw fail(HttpStatus.BAD_REQUEST,"SHOP_CREDIT_CODE_INVALID");if(row("SELECT id FROM t_stores WHERE owner_id=? FOR UPDATE",user)!=null||!db.queryForList("SELECT id FROM t_store_applications WHERE user_id=? AND status='pending' FOR UPDATE",user).isEmpty())throw fail(HttpStatus.CONFLICT,"SHOP_APPLICATION_ALREADY_EXISTS");
  if(invite!=null&&row("SELECT id FROM t_profiles WHERE my_invite_code=? AND deleted_at IS NULL AND id<>?",invite,user)==null)throw fail(HttpStatus.BAD_REQUEST,"SHOP_INVITATION_INVALID");
  var upload=row("SELECT id,kind,sha256,byte_size,consumed_at FROM t_community_uploads WHERE id=? AND user_id=? AND purpose='store_license' FOR UPDATE",input.licenseUploadId(),user);if(upload==null||!"document".equals(upload.get("kind"))||upload.get("sha256")==null||!upload.get("sha256").toString().matches("[a-f0-9]{64}")||!(upload.get("byte_size") instanceof Number bytes)||bytes.longValue()<1||upload.get("consumed_at")!=null)throw fail(HttpStatus.BAD_REQUEST,"SHOP_LICENSE_UPLOAD_REQUIRED");
  changed(db.update("INSERT INTO t_store_applications(id,user_id,business_name,unified_social_credit_code,legal_representative,license_upload_id,invitation_code,application_channel,status) VALUES(?,?,?,?,?,?,?,?,'pending')",application,user,input.businessName().trim(),input.creditCode(),input.representative().trim(),input.licenseUploadId(),invite,input.channel()));changed(db.update("UPDATE t_community_uploads SET consumed_at=CURRENT_TIMESTAMP(3) WHERE id=? AND user_id=? AND consumed_at IS NULL",input.licenseUploadId(),user));return Map.of("id",application,"status","pending");
 }
 public List<Map<String,Object>> queue(int limit,int offset){guard.requireAdmin();if(limit<1||limit>100||offset<0)throw fail(HttpStatus.BAD_REQUEST,"SHOP_INVALID_PAGE");return db.queryForList("SELECT a.id,a.user_id,a.business_name,a.unified_social_credit_code,a.legal_representative,a.license_upload_id,a.invitation_code,a.application_channel,a.status,a.review_note,a.reviewed_by,a.reviewed_at,a.created_at,s.id AS store_id,s.status AS store_status,u.content_type AS license_content_type FROM t_store_applications a LEFT JOIN t_stores s ON s.application_id=a.id LEFT JOIN t_community_uploads u ON u.id=a.license_upload_id ORDER BY CASE WHEN a.status='pending' THEN 0 ELSE 1 END,a.created_at,a.id LIMIT ? OFFSET ?",limit,offset);}
 @Transactional public Map<String,String> review(String application,Review input){String actor=guard.requireAdmin();var initial=row("SELECT user_id FROM t_store_applications WHERE id=?",application);if(initial==null)throw fail(HttpStatus.NOT_FOUND,"SHOP_APPLICATION_UNAVAILABLE");String user=initial.get("user_id").toString();lockOwner(user);var app=row("SELECT id,status,business_name,review_note,reviewed_by FROM t_store_applications WHERE id=? FOR UPDATE",application);String next=input.approve()?"approved":"rejected";if(!"pending".equals(app.get("status"))){if(next.equals(app.get("status"))&&actor.equals(app.get("reviewed_by"))&&input.reason().trim().equals(app.get("review_note")))return Map.of("id",application,"status",next);throw fail(HttpStatus.CONFLICT,"SHOP_REVIEW_CHANGED");}if(input.approve()){if(row("SELECT id FROM t_stores WHERE owner_id=? FOR UPDATE",user)!=null)throw fail(HttpStatus.CONFLICT,"SHOP_ALREADY_EXISTS");String store=UUID.nameUUIDFromBytes(("store:"+user).getBytes(StandardCharsets.UTF_8)).toString();changed(db.update("INSERT INTO t_stores(id,owner_id,application_id,name,description,matching_fee_rate,status) VALUES(?,?,?,?,'',5.00,'active')",store,user,application,app.get("business_name")));}changed(db.update("UPDATE t_store_applications SET status=?,review_note=?,reviewed_by=?,reviewed_at=CURRENT_TIMESTAMP(3) WHERE id=? AND status='pending'",next,input.reason().trim(),actor,application));audit(actor,"shop_application_review",application,input.reason().trim());notice(user,input.approve()?"店铺申请已通过，请完善资料与商品":"店铺申请未通过，请查看审核意见");return Map.of("id",application,"status",next);}
 private Map<String,Object> ownStore(String user){lockOwner(user);var shop=row("SELECT id,status FROM t_stores WHERE owner_id=? FOR UPDATE",user);if(shop==null)throw fail(HttpStatus.NOT_FOUND,"SHOP_UNAVAILABLE");return shop;}
 @Transactional public void edit(Edit input){String user=guard.requireActiveProfile();var shop=ownStore(user);changed(db.update("UPDATE t_stores SET name=?,description=? WHERE id=?",input.name().trim(),input.description()==null?"":input.description().trim(),shop.get("id")));}
 @Transactional public void state(String id,State input,boolean admin){String actor=admin?guard.requireAdmin():guard.requireActiveProfile();var initial=row("SELECT owner_id FROM t_stores WHERE id=?",id);if(initial==null||!admin&&!actor.equals(initial.get("owner_id")))throw fail(HttpStatus.NOT_FOUND,"SHOP_UNAVAILABLE");String owner=initial.get("owner_id").toString();var shop=ownStore(owner);String current=shop.get("status").toString();if(!current.equals(input.expectedStatus()))throw fail(HttpStatus.CONFLICT,"SHOP_STATE_CHANGED");if(!admin&&(current.equals("suspended")||input.status().equals("suspended")))throw fail(HttpStatus.FORBIDDEN,"SHOP_ADMIN_REQUIRED");changed(db.update("UPDATE t_stores SET status=? WHERE id=? AND status=?",input.status(),id,current));if(admin)audit(actor,"shop_status",id,input.reason().trim());notice(owner,"店铺状态已更新，请查看经营状态");}
 @Transactional public void link(String productId,boolean remove){String user=remove?guard.requireActiveProfile():guard.requireVerifiedCarrier();var shop=ownStore(user);if(!Set.of("active","paused").contains(shop.get("status")))throw fail(HttpStatus.CONFLICT,"SHOP_SUSPENDED");if(row("SELECT id FROM t_products WHERE id=? AND owner_id=? FOR UPDATE",productId,user)==null)throw fail(HttpStatus.NOT_FOUND,"SHOP_PRODUCT_UNAVAILABLE");if(remove)db.update("DELETE FROM t_store_products WHERE store_id=? AND product_id=?",shop.get("id"),productId);else {db.update("INSERT IGNORE INTO t_store_products(store_id,product_id,created_by) VALUES(?,?,?)",shop.get("id"),productId,user);var binding=row("SELECT store_id FROM t_store_products WHERE product_id=? FOR UPDATE",productId);if(binding==null||!shop.get("id").equals(binding.get("store_id")))throw fail(HttpStatus.CONFLICT,"SHOP_PRODUCT_ALREADY_LINKED");}}
 public List<Map<String,Object>> linked(int limit,int offset){String user=guard.requireActiveProfile();if(limit<1||limit>100||offset<0)throw fail(HttpStatus.BAD_REQUEST,"SHOP_INVALID_PAGE");return db.queryForList("SELECT p.id,p.name,p.status,p.stock,p.price FROM t_store_products sp JOIN t_stores s ON s.id=sp.store_id JOIN t_products p ON p.id=sp.product_id AND p.owner_id=s.owner_id WHERE s.owner_id=? ORDER BY sp.created_at DESC,p.id LIMIT ? OFFSET ?",user,limit,offset);}
 public Map<String,Object> publicShop(String id,int limit,int offset){if(limit<1||limit>100||offset<0)throw fail(HttpStatus.BAD_REQUEST,"SHOP_INVALID_PAGE");var store=row("SELECT s.id,s.name,s.description,s.created_at FROM t_stores s JOIN t_profiles p ON p.id=s.owner_id WHERE s.id=? AND s.status='active' AND p.deleted_at IS NULL AND (p.banned_until IS NULL OR p.banned_until<=CURRENT_TIMESTAMP(3))",id);if(store==null)throw fail(HttpStatus.NOT_FOUND,"SHOP_UNAVAILABLE");var result=new LinkedHashMap<String,Object>(store);result.put("products",db.queryForList("SELECT p.id,p.name,p.spec,p.region,p.price,p.stock,p.image_urls FROM t_store_products sp JOIN t_stores s ON s.id=sp.store_id JOIN t_products p ON p.id=sp.product_id AND p.owner_id=s.owner_id JOIN t_profiles u ON u.id=p.owner_id WHERE sp.store_id=? AND s.status='active' AND p.status='on' AND p.stock>0 AND u.deleted_at IS NULL AND u.carrier_verify_status='approved' AND (u.banned_until IS NULL OR u.banned_until<=CURRENT_TIMESTAMP(3)) ORDER BY sp.created_at DESC,p.id LIMIT ? OFFSET ?",id,limit,offset));return result;}
 private void audit(String actor,String action,String target,String reason){changed(db.update("INSERT INTO t_admin_logs(id,operator_id,action,target_type,target_id,detail) VALUES(?,?,?,'store',?,?)",UUID.randomUUID().toString(),actor,action,target,reason));}
 private void notice(String user,String body){changed(db.update("INSERT INTO t_notifications(id,user_id,kind,title,body) VALUES(?,?,'store','店铺经营进度',?)",UUID.randomUUID().toString(),user,body));}
}
